package sn.grainettable;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Service
public class CatalogService {
 final JdbcTemplate db;
 public CatalogService(JdbcTemplate db){this.db=db;}
 public void health(){db.queryForObject("SELECT 1",Integer.class);}
 static String clean(String s){return s==null?"":s.trim();}
 static long num(Object n){return ((Number)n).longValue();}
 static void page(int page,int limit){if(page<1||page>100000||limit<1||limit>100)throw new ApiException(400,"Pagination invalide");}
 Map<String,Object> list(String select,String count,List<Object> args,int page,int limit){page(page,limit);long total=db.queryForObject(count,Long.class,args.toArray());var values=new ArrayList<>(args);values.add(limit);values.add((page-1)*limit);return Map.of("items",db.queryForList(select+" LIMIT ? OFFSET ?",values.toArray()),"total",total,"page",page,"limit",limit,"pages",(total+limit-1)/limit);}
 public Map<String,Object> products(String q,Long category,Long min,Long max,boolean available,String sort,int page,int limit,boolean admin,String status){var args=new ArrayList<Object>();var clauses=new ArrayList<String>();if(!admin){clauses.add("p.status='published'");clauses.add("c.visible=TRUE");}if(!clean(q).isEmpty()){clauses.add("(LOWER(p.name) LIKE ? OR LOWER(p.sku) LIKE ?)");args.add("%"+clean(q).toLowerCase(Locale.ROOT)+"%");args.add(args.getLast());}if(category!=null){clauses.add("p.category_id=?");args.add(category);}if(min!=null){if(min<0)throw new ApiException(400,"Prix invalide");clauses.add("p.price>=?");args.add(min);}if(max!=null){if(max<0)throw new ApiException(400,"Prix invalide");clauses.add("p.price<=?");args.add(max);}if(available)clauses.add("p.stock>0");if(admin&&!clean(status).isEmpty()){if(!Set.of("draft","published").contains(status))throw new ApiException(400,"Statut invalide");clauses.add("p.status=?");args.add(status);}String ordering=switch(sort){case "selection"->"p.id DESC";case "price_asc"->"p.price,p.id";case "price_desc"->"p.price DESC,p.id";case "name"->"p.name,p.id";default->throw new ApiException(400,"Tri invalide");};String from=" FROM product p JOIN category c ON c.id=p.category_id"+(clauses.isEmpty()?"":" WHERE "+String.join(" AND ",clauses));return list("SELECT p.*,c.name AS category_name"+from+" ORDER BY "+ordering,"SELECT COUNT(*)"+from,args,page,limit);}
 public Map<String,Object> product(long id){var rows=db.queryForList("SELECT p.*,c.name AS category_name FROM product p JOIN category c ON c.id=p.category_id WHERE p.id=? AND p.status='published' AND c.visible=TRUE",id);if(rows.isEmpty())throw new ApiException(404,"Produit introuvable");return rows.getFirst();}
 public List<Map<String,Object>> categories(boolean admin){return db.queryForList("SELECT c.*,COUNT(p.id) AS product_count FROM category c LEFT JOIN product p ON p.category_id=c.id"+(admin?"":" AND p.status='published'")+(admin?"":" WHERE c.visible=TRUE")+" GROUP BY c.id ORDER BY c.id");}
 @Transactional public Map<String,Object> saveCategory(Long id,Requests.Category p){if(id==null){db.update("INSERT INTO category(name,slug,description,visible) VALUES(?,?,?,?)",p.name().trim(),p.slug(),clean(p.description()),p.visible());return db.queryForMap("SELECT * FROM category WHERE slug=?",p.slug());}if(db.update("UPDATE category SET name=?,slug=?,description=?,visible=? WHERE id=?",p.name().trim(),p.slug(),clean(p.description()),p.visible(),id)==0)throw new ApiException(404,"Catégorie introuvable");return db.queryForMap("SELECT * FROM category WHERE id=?",id);}
 @Transactional public void deleteCategory(long id){if(db.queryForObject("SELECT COUNT(*) FROM product WHERE category_id=?",Long.class,id)>0)throw new ApiException(409,"Réaffectez les produits avant de supprimer la catégorie");if(db.update("DELETE FROM category WHERE id=?",id)==0)throw new ApiException(404,"Catégorie introuvable");}
 @Transactional public Map<String,Object> saveProduct(Long id,Requests.Product p){if(db.queryForObject("SELECT COUNT(*) FROM category WHERE id=?",Long.class,p.categoryId())==0)throw new ApiException(400,"Catégorie introuvable");if(id==null){db.update("INSERT INTO product(name,sku,description,category_id,price,stock,status,image) VALUES(?,?,?,?,?,?,?,?)",p.name().trim(),p.sku().trim(),clean(p.description()),p.categoryId(),p.price(),p.stock(),p.status(),p.image());return db.queryForMap("SELECT * FROM product WHERE sku=?",p.sku().trim());}if(db.update("UPDATE product SET name=?,sku=?,description=?,category_id=?,price=?,stock=?,status=?,image=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",p.name().trim(),p.sku().trim(),clean(p.description()),p.categoryId(),p.price(),p.stock(),p.status(),p.image(),id)==0)throw new ApiException(404,"Produit introuvable");return db.queryForMap("SELECT * FROM product WHERE id=?",id);}
 public void archive(long id){if(db.update("UPDATE product SET status='draft',updated_at=CURRENT_TIMESTAMP WHERE id=?",id)==0)throw new ApiException(404,"Produit introuvable");}
}
